<?php require __DIR__.'/includes/bootstrap.php';require_permission('audit.view');require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';$page=max(1,(int)($_GET['page']??1));$per=30;$total=(int)$pdo->query('SELECT COUNT(*) FROM audit_logs')->fetchColumn();$rows=$pdo->query('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT '.$per.' OFFSET '.(($page-1)*$per))->fetchAll();render_header('Audit Logs','audit');page_title('Audit Logs','SECURITY & TRACEABILITY','Review immutable user actions, exports, logins and data changes.');?><article class="card table-card"><div class="table-toolbar"><b><?=number_format($total)?> audit events</b><input placeholder="Search events…" data-table-search></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Module</th><th>Record</th><th>IP Address</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td data-label="Time"><?=date('d M Y H:i:s',strtotime($r['created_at']))?></td><td data-label="User"><?=e($r['name']??'System')?></td><td data-label="Action"><span class="status"><?=e($r['action'])?></span></td><td data-label="Module"><?=e($r['module'])?></td><td data-label="Record"><?=e($r['record_id']??'—')?></td><td data-label="IP Address"><?=e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div><?php pager($page,(int)ceil($total/$per));?></article><?php render_footer('audit');
